                                    ds.officeArea * this.BASE_RENT_OFFICE) * 12;
                var projectedVacancy = projectedGPR * 0.06;
                var projectedEGI = projectedGPR - projectedVacancy;
                var projectedOpEx = projectedEGI * 0.30;
                var projectedNOI = projectedEGI - projectedOpEx;
                var projectedValue = projectedNOI / this.MARKET_CAP_RATE;
                var estimatedTDC = ds.landCost + ds.hardCosts * 1.35;
                var residualLandValue = projectedValue - (ds.hardCosts * 1.35);

                results.landCost = ds.landCost;
                results.residentialUnits = ds.residentialUnits;
                results.retailArea = ds.retailArea;
                results.officeArea = ds.officeArea;
                results.feasibilityCost = ds.feasibilityCost;
                results.residualLandValue = Math.round(residualLandValue);
                results.landPremium = Math.round(ds.landCost - residualLandValue);
                results.projectedNOI = Math.round(projectedNOI);

                ds.totalDevelopmentCost = ds.landCost + ds.feasibilityCost;
                ds.equityInvested = ds.totalDevelopmentCost;
                ds.annualNOI = 0;
                ds.occupancyRate = 0;

            } else if (period === 2) {
                var engCosts = { minimum: 20000, proactive: 80000, full: 180000 };
                var archCosts = { local: 150000, international: 350000, designbuild: 250000 };
                ds.engagementLevel = d.engagement;
                ds.architectType = d.architect;
                ds.engagementCost = engCosts[d.engagement] || 80000;
                ds.architectCost = archCosts[d.architect] || 150000;

                ds.delayPenalty = 0;
                var delayTriggered = false;
                if (d.engagement === 'minimum') {
                    if (ds.feasibilityLevel !== 'deep') {
                        ds.delayPenalty = Math.round(ds.landCost * this.BASE_INTEREST_RATE * 0.25);
                        delayTriggered = true;
                        ds.eventLog.push('entitlement_delay');
                    }
                }

                ds.preDevelopmentCosts = ds.feasibilityCost + ds.engagementCost + ds.architectCost + ds.delayPenalty;
                ds.totalDevelopmentCost = ds.landCost + ds.preDevelopmentCosts;
                ds.equityInvested = ds.totalDevelopmentCost;

                results.engagementCost = ds.engagementCost;
                results.architectCost = ds.architectCost;
                results.delayPenalty = ds.delayPenalty;
                results.delayTriggered = delayTriggered;
                results.preDevelopmentCosts = ds.preDevelopmentCosts;

                if (delayTriggered) {
                    this._showEvent(
                        t('event_delay_title'),
                        t('event_delay_text')
                    );
                }

            } else if (period === 3) {
                ds.ltcRatio = d.ltcRatio;
                ds.hedged = d.hedge;
                ds.softCosts = Math.round(ds.hardCosts * this.SOFT_COST_PCT);
                ds.devFee = Math.round((ds.hardCosts + ds.softCosts) * this.DEV_FEE_PCT);

                var rateShock = 0.015;
                ds.effectiveRate = ds.hedged ? this.BASE_INTEREST_RATE : this.BASE_INTEREST_RATE + rateShock;
                var hedgeCost = 0;
                if (ds.hedged) {
                    hedgeCost = Math.round(ds.hardCosts * 0.6 * 0.008);
                }
                ds.eventLog.push('rate_shock');

                var subtotal = ds.landCost + ds.hardCosts + ds.softCosts + ds.devFee + ds.preDevelopmentCosts;
                ds.constructionLoan = Math.round(subtotal * d.ltcRatio / 100);
                ds.interestCost = Math.round(ds.constructionLoan * ds.effectiveRate * d.interestReserve / 12);
                ds.totalDevelopmentCost = subtotal + ds.interestCost + hedgeCost;
                ds.equityInvested = ds.totalDevelopmentCost - ds.constructionLoan;

                var equityCostMod = { institutional: 1.0, family: 1.05, internal: 1.15 };
                var mod = equityCostMod[d.equitySource] || 1.05;
                ds.equityInvested = Math.round(ds.equityInvested * mod);

                results.constructionLoan = ds.constructionLoan;
                results.interestCost = ds.interestCost;
                results.hedgeCost = hedgeCost;
                results.effectiveRate = ds.effectiveRate;
                results.totalDevelopmentCost = ds.totalDevelopmentCost;
                results.equityInvested = ds.equityInvested;
                results.rateShockImpact = !ds.hedged ? Math.round(ds.constructionLoan * rateShock * d.interestReserve / 12) : 0;

                this._showEvent(
                    t('event_rate_title'),
                    ds.hedged ? t('event_rate_hedged') : t('event_rate_unhedged')
                );

            } else if (period === 4) {
                ds.contractType = d.contractType;
                ds.contingencyPct = d.contingencyPct;

                var costSurge = 0.12;
                var absorbedByDev = d.contractType === 'gmp' ? 0.03 : costSurge;
                var overrunAmount = Math.round(ds.hardCosts * absorbedByDev);
                ds.contingencyAmount = Math.round(ds.hardCosts * d.contingencyPct / 100);
                ds.overrunCost = Math.max(0, overrunAmount - ds.contingencyAmount);

                var pacePremium = 0;
                var paceInterestSaving = 0;
                if (d.pace === 'accelerated') {
                    pacePremium = Math.round(ds.hardCosts * 0.15);
                    paceInterestSaving = Math.round(ds.constructionLoan * ds.effectiveRate * 0.25);
                }

                ds.hardCosts = ds.hardCosts + overrunAmount + pacePremium;
                ds.totalDevelopmentCost = ds.totalDevelopmentCost + ds.overrunCost + pacePremium - paceInterestSaving;
                ds.equityInvested = ds.equityInvested + ds.overrunCost + pacePremium - paceInterestSaving;
                ds.eventLog.push('cost_surge');

                results.costSurgeImpact = overrunAmount;
                results.contingencyUsed = Math.min(ds.contingencyAmount, overrunAmount);
                results.additionalEquityNeeded = ds.overrunCost;
                results.pacePremium = pacePremium;
                results.paceInterestSaving = paceInterestSaving;
                results.totalDevelopmentCost = ds.totalDevelopmentCost;

                this._showEvent(
                    t('event_cost_title'),
                    d.contractType === 'gmp' ? t('event_cost_gmp') : t('event_cost_costplus')
                );

            } else if (period === 5) {
                var rentMult = { below: 0.90, at: 1.0, above: 1.10 };
                ds.rentMultiplier = rentMult[d.rentPositioning] || 1.0;

                var concFactor = { none: 0, '1month': 1/12, '2months': 2/12 };
                ds.concessionFactor = concFactor[d.concessions] || 0;
                ds.retailTenantType = d.retailTenant;

                var mktCosts = { digital: 50000, broker: 120000, modelunit: 200000 };
                ds.marketingCost = mktCosts[d.marketing] || 120000;

                var oversupplyHit = 0;
                if (ds.residentialPct > 75) {
                    oversupplyHit = 0.08;
                    ds.eventLog.push('oversupply');
                }

                var effResRent = this.BASE_RENT_RESIDENTIAL * ds.rentMultiplier * (1 - oversupplyHit) * (1 - ds.concessionFactor);
                var retailRentMult = { fnb: 0.85, pharmacy: 0.90, fitness: 1.0, none: 0 };
                var retailOccMult = { fnb: 1.0, pharmacy: 1.0, fitness: 0.90, none: 0 };
                var effRetailRent = this.BASE_RENT_RETAIL * (retailRentMult[d.retailTenant] || 0);
                var retailOcc = retailOccMult[d.retailTenant] || 0;

                var baseAbsorption = 0.55;
                if (d.rentPositioning === 'below') baseAbsorption += 0.15;
                if (d.rentPositioning === 'above') baseAbsorption -= 0.10;
                if (d.marketing === 'broker') baseAbsorption += 0.10;
                if (d.marketing === 'modelunit') baseAbsorption += 0.18;
                if (d.concessions !== 'none') baseAbsorption += 0.05;
                baseAbsorption -= oversupplyHit * 0.5;
                ds.occupancyRate = Math.min(0.92, Math.max(0.30, baseAbsorption));

                var resGPR = ds.residentialArea * effResRent * 12 * ds.occupancyRate;
                var retGPR = ds.retailArea * effRetailRent * 12 * retailOcc;
                var offGPR = ds.officeArea * this.BASE_RENT_OFFICE * 12 * 0.45;

                var retailSaleIncome = 0;
                if (d.retailTenant === 'none') {
                    retailSaleIncome = ds.retailArea * 800;
                    retGPR = 0;
                }

                var totalGPR = resGPR + retGPR + offGPR;
                var vacancy = totalGPR * 0.03;
                var egi = totalGPR - vacancy;
                var opEx = egi * 0.30;
                ds.annualNOI = Math.round(egi - opEx);
                ds.totalDevelopmentCost += ds.marketingCost;
                ds.equityInvested += ds.marketingCost;

                results.effectiveResRent = Math.round(effResRent * 100) / 100;
                results.occupancyRate = Math.round(ds.occupancyRate * 100);
                results.annualNOI = ds.annualNOI;
                results.marketingCost = ds.marketingCost;
                results.retailSaleIncome = retailSaleIncome;
                results.oversupplyTriggered = oversupplyHit > 0;

                if (oversupplyHit > 0) {
                    this._showEvent(
                        t('event_supply_title'),
                        t('event_supply_text')
                    );
                }

            } else if (period === 6) {
                var occAdj = 0;
                var rentAdj = 0;
                if (d.renewal === 'decrease') { occAdj += 0.05; rentAdj -= 0.05; }
                if (d.renewal === 'maintain') { occAdj += 0.03; }
                if (d.renewal === 'increase') { occAdj += 0.01; rentAdj += 0.05; }

                if (d.management === 'self') { occAdj -= 0.02; }
                if (d.management === 'company') { occAdj += 0.03; }

                if (d.vacancy === 'shortterm') { occAdj += 0.08; rentAdj -= 0.04; }
                if (d.vacancy === 'holdlong') { occAdj += 0.02; }

                ds.occupancyRate = Math.min(0.96, ds.occupancyRate + occAdj);

                var anchorDefault = false;
                if (ds.retailTenantType === 'fnb') {
                    anchorDefault = true;
                    ds.eventLog.push('anchor_default');
                }

                var effResRent2 = this.BASE_RENT_RESIDENTIAL * ds.rentMultiplier * (1 + rentAdj);
                var retRentNow = anchorDefault ? 0 : this.BASE_RENT_RETAIL * 0.90;
                var retOccNow = anchorDefault ? 0.30 : 0.95;
                var mgmtCostMult = d.management === 'company' ? 1.05 : 0.98;

                var resGPR2 = ds.residentialArea * effResRent2 * 12 * ds.occupancyRate;
                var retGPR2 = ds.retailTenantType !== 'none' ? ds.retailArea * retRentNow * 12 * retOccNow : 0;
                var offGPR2 = ds.officeArea * this.BASE_RENT_OFFICE * 12 * 0.55;
                var totalGPR2 = resGPR2 + retGPR2 + offGPR2;
                var vacancy2 = totalGPR2 * 0.02;
                var egi2 = totalGPR2 - vacancy2;
                var opEx2 = egi2 * 0.28 * mgmtCostMult;
                ds.stabilizedNOI = Math.round(egi2 - opEx2);
                ds.annualNOI = ds.stabilizedNOI;

                ds.developmentYield = ds.totalDevelopmentCost > 0 ? ds.stabilizedNOI / ds.totalDevelopmentCost : 0;
                ds.marketValue = Math.round(ds.stabilizedNOI / this.MARKET_CAP_RATE);

                results.occupancyRate = Math.round(ds.occupancyRate * 100);
                results.stabilizedNOI = ds.stabilizedNOI;
                results.developmentYield = Math.round(ds.developmentYield * 10000) / 100;
                results.marketValue = ds.marketValue;
                results.anchorDefault = anchorDefault;

                if (anchorDefault) {
                    this._showEvent(
                        t('event_anchor_title'),
                        t('event_anchor_text')
                    );
                }

            } else if (period === 7) {
                ds.exitStrategy = d.exit;
                var exitCapRate = this.MARKET_CAP_RATE + 0.005;
                var debtService = ds.constructionLoan * ds.effectiveRate;
                var annualCashFlow = ds.stabilizedNOI - debtService;

                if (d.exit === 'sell') {
                    var salePrice = Math.round(ds.stabilizedNOI / exitCapRate);
                    var closingCosts = Math.round(salePrice * 0.02);
                    var loanPayoff = ds.constructionLoan;
                    ds.netProceeds = salePrice - closingCosts - loanPayoff;
                    ds.equityMultiple = ds.equityInvested > 0 ? Math.round((ds.netProceeds / ds.equityInvested) * 100) / 100 : 0;
                    results.salePrice = salePrice;
                    results.closingCosts = closingCosts;
                    results.netProceeds = ds.netProceeds;
                } else if (d.exit === 'hold') {
                    var holdValue = Math.round(annualCashFlow / 0.08);
                    ds.netProceeds = holdValue;
                    ds.equityMultiple = ds.equityInvested > 0 ? Math.round(((ds.equityInvested + annualCashFlow * 5) / ds.equityInvested) * 100) / 100 : 0;
                    results.annualCashFlow = Math.round(annualCashFlow);
                    results.holdValue = holdValue;
                    results.netProceeds = ds.netProceeds;
                } else {
                    var permRate = ds.effectiveRate - 0.01;
                    var dscr = 1.25;
                    var maxDebtService = ds.stabilizedNOI / dscr;
                    var permLoan = Math.round(maxDebtService / permRate);
                    var cashOut = permLoan - ds.constructionLoan;
                    ds.netProceeds = Math.max(0, cashOut);
                    ds.equityMultiple = ds.equityInvested > 0 ? Math.round(((ds.netProceeds + ds.equityInvested * 0.3) / ds.equityInvested) * 100) / 100 : 0;
                    results.permLoan = permLoan;
                    results.cashOut = cashOut;
                    results.netProceeds = ds.netProceeds;
                }

                ds.developmentYield = ds.totalDevelopmentCost > 0 ? ds.stabilizedNOI / ds.totalDevelopmentCost : 0;
                ds.cashOnCash = ds.equityInvested > 0 ? annualCashFlow / ds.equityInvested : 0;

                var devSpread = ds.developmentYield - this.MARKET_CAP_RATE;
                results.equityMultiple = ds.equityMultiple;
                results.developmentYield = Math.round(ds.developmentYield * 10000) / 100;
                results.cashOnCash = Math.round(ds.cashOnCash * 10000) / 100;
                results.developmentSpread = Math.round(devSpread * 10000);
                results.totalDevelopmentCost = ds.totalDevelopmentCost;
                results.equityInvested = ds.equityInvested;
                results.exitStrategy = d.exit;
            }

            var phaseIdx = Math.min(period - 1, this.PHASES.length - 1);
            ds.phaseNames.push(this.PHASES[phaseIdx]);
            ds.noiHistory.push(ds.annualNOI);
            ds.equityHistory.push(ds.equityInvested);
            ds.occupancyHistory.push(Math.round(ds.occupancyRate * 100));
            ds.yieldHistory.push(Math.round((ds.developmentYield || 0) * 10000) / 100);
            ds.costHistory.push(ds.totalDevelopmentCost);

            results.totalDevelopmentCost = ds.totalDevelopmentCost;
            results.equityInvested = ds.equityInvested;
            results.annualNOI = ds.annualNOI;
            results.occupancyRate = Math.round(ds.occupancyRate * 100);

            // platform score: same two metrics getPerformanceSummary bands into a verdict, development spread over the market cap rate and the equity multiple, each mapped onto half of a 0 to 100 line so the Competent, Skilled and Expert thresholds land near 40, 68 and 100
            var devSpreadBps = Math.round((ds.developmentYield - this.MARKET_CAP_RATE) * 10000);
            var spreadScore = Math.max(0, Math.min(50, devSpreadBps / 200 * 50));
            var eqScore = Math.max(0, Math.min(50, (ds.equityMultiple - 1) / 1 * 50));
            var overallScore = Math.max(0, Math.min(100, Math.round(spreadScore + eqScore)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return results;
        }

        _showEvent(title, text) {
            // Stash the event; _updateBriefing renders it when the view advances to
            // the next round, so it stays visible while the player reads consequences
            // and decides (previously the advance hid it ~500ms after it appeared).
            this._pendingEvent = { title: title, text: text };
        }

