            uiManager.bind('tdcDisplay', 'domainState.totalDevelopmentCost',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('noiDisplay', 'domainState.annualNOI',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('occupancyDisplay', 'domainState.occupancyRate',
                (v) => Math.round(v * 100) + '%');
            uiManager.bind('yieldDisplay', 'domainState.developmentYield',
                (v) => (Math.round(v * 10000) / 100).toFixed(1) + '%');
            uiManager.bind('multipleDisplay', 'domainState.equityMultiple',
                (v) => (v || 0).toFixed(2) + 'x');
        }

