        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var ds = window.mySimulation.state.domainState;

            var devYield = r.developmentYield || 0;
            var eqMult = r.equityMultiple || ds.equityMultiple || 0;
            var devSpread = r.developmentSpread || 0;
            var noi = ds.stabilizedNOI || ds.annualNOI || 0;

            var performance = 'Needs Improvement';
            if (devSpread > 100 && eqMult > 1.3) performance = 'Competent Developer';
            if (devSpread > 150 && eqMult > 1.6) performance = 'Skilled Developer';
            if (devSpread > 200 && eqMult > 2.0) performance = 'Expert Developer';

            var insights = [];
            if (devSpread < 0) {
                insights.push('The development spread is negative. The project destroyed value relative to buying a stabilized asset.');
            } else if (devSpread < 100) {
                insights.push('A thin development spread suggests the risk was not adequately compensated.');
            } else {
                insights.push('A healthy development spread indicates genuine value creation through the development process.');
            }

            if (eqMult < 1.0) {
                insights.push('Equity multiple below 1.0x means investors lost money on this project.');
            } else if (eqMult < 1.5) {
                insights.push('The equity return is modest. Higher leverage or better lease-up could improve returns.');
            } else {
                insights.push('Strong equity returns demonstrate effective capital deployment and risk management.');
            }

            if (ds.eventLog.indexOf('entitlement_delay') >= 0) {
                insights.push('The entitlement delay added unnecessary carrying costs. Community engagement is insurance, not expense.');
            }

            return {
                stabilizedNOI: noi,
                developmentYield: devYield,
                equityMultiple: eqMult,
                developmentSpread: devSpread,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var period = state.currentPeriod;
            var t = window.mySimulation.t.bind(window.mySimulation);

            if (period === 1 && results.landPremium > 200000) {
                return t('hint_overpaid');
            }
            if (period === 3 && !state.domainState.hedged) {
                return t('hint_unhedged');
            }
            if (period === 5 && results.oversupplyTriggered) {
                return t('hint_oversupply');
            }
            if (period === 6 && results.anchorDefault) {
                return t('hint_anchor');
            }
            if (period === 7) {
                var ds = state.domainState;
                if (ds.developmentYield > 0 && ds.developmentYield - this.MARKET_CAP_RATE > 0.015) {
                    return t('hint_value_created');
                }
                if (ds.developmentYield > 0 && ds.developmentYield - this.MARKET_CAP_RATE < 0) {
                    return t('hint_value_destroyed');
                }
            }
            return null;
        }

